def merge_intervals(intervals):
    if not intervals:
        return []
    merged = []
    for start, end in sorted(intervals, key=lambda iv: (iv[0], iv[1])):
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

import heapq

def toposort(nodes, edges):
    unique_edges = set(edges)
    adj = {node: [] for node in nodes}
    indegree = {node: 0 for node in nodes}
    for source, destination in unique_edges:
        adj[source].append(destination)
        indegree[destination] += 1

    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")
    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("invalid weight")
    batches = []
    current = []
    current_sum = 0
    for name, weight in items:
        if current and current_sum + weight > limit:
            batches.append(current)
            current = []
            current_sum = 0
        current.append(name)
        current_sum += weight
    if current:
        batches.append(current)
    return batches

import re

def parse_env(text):
    env = {}
    key_re = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError('invalid line: %r' % line)
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        if not key_re.fullmatch(key):
            raise ValueError('invalid key: %r' % key)
        if len(value) >= 2 and value[0] == value[-1] and value[0] in "'\"":
            value = value[1:-1]
        env[key] = value
    return env

def parse_sse(chunks):
    text = b''.join(chunks).decode('utf-8')
    events = []
    data_lines = []
    i = 0
    n = len(text)
    while i < n:
        nl = text.find('\n', i)
        if nl == -1:
            line = text[i:]
            i = n
        else:
            line = text[i:nl]
            if line.endswith('\r'):
                line = line[:-1]
            i = nl + 1

        if line == '':
            if data_lines:
                data = '\n'.join(data_lines)
                if data == '[DONE]':
                    return events
                events.append(data)
                data_lines = []
            continue

        if line.startswith(':'):
            continue

        if ':' in line:
            field, _, value = line.partition(':')
            if value.startswith(' '):
                value = value[1:]
        else:
            field, value = line, ''

        if field == 'data':
            data_lines.append(value)

    return events

import math

def retry_delay(attempt, base, cap):
    if attempt < 0:
        raise ValueError("attempt must be nonnegative")
    if base < 0 or cap < 0:
        raise ValueError("base and cap must be nonnegative")
    try:
        b = float(base)
        c = float(cap)
    except (OverflowError, ValueError) as e:
        raise ValueError("base and cap must be finite") from e
    if not (math.isfinite(b) and math.isfinite(c)):
        raise ValueError("base and cap must be finite")
    if b == 0.0 or c == 0.0:
        return 0.0
    if attempt <= 1000:
        p = b * (2.0 ** float(attempt))
    else:
        log_p = math.log(b) + float(attempt) * math.log(2.0)
        if log_p >= 709.782712893384:
            return c
        p = math.exp(log_p)
    return min(c, p)

def fifo_admit(active, queued, budget, slots):
    for reservation in queued:
        if reservation > budget:
            raise ValueError("queued reservation exceeds budget")

    remaining_tokens = budget - sum(active)
    remaining_slots = slots - len(active)
    admitted = []
    index = 0

    for reservation in queued:
        if remaining_slots > 0 and reservation <= remaining_tokens:
            admitted.append(reservation)
            remaining_tokens -= reservation
            remaining_slots -= 1
            index += 1
        else:
            break

    return admitted, queued[index:]
